# ===== main.py =====
from typing import Any, Dict

from fastapi import Body, FastAPI, Request
from fastapi.exception_handlers import http_exception_handler
from fastapi.responses import JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException

app = FastAPI(title="Health and Echo API")


@app.exception_handler(StarletteHTTPException)
async def _http_exc(request: Request, exc: StarletteHTTPException):
    # FastAPI reports undecodable bodies (e.g. invalid UTF-8) as 400;
    # for /echo these are validation failures, so report 422.
    if request.url.path == "/echo" and exc.status_code == 400:
        return JSONResponse(status_code=422, content={"detail": str(exc.detail)})
    return await http_exception_handler(request, exc)


@app.get("/health")
def health() -> dict:
    return {"status": "ok"}


@app.post("/echo")
def echo(payload: Dict[str, Any] = Body(...)) -> Dict[str, Any]:
    return payload


# ===== test_validation.py =====
import pytest
from fastapi.testclient import TestClient

from main import app

client = TestClient(app)
JSON_HDR = {"Content-Type": "application/json"}


def assert_422(r):
    assert r.status_code == 422
    assert r.headers["content-type"].startswith("application/json")
    assert "detail" in r.json()


@pytest.mark.parametrize("raw", ['{"a": ', "{bad json}", "{'a': 1}", '{"a": 1,}', "not json"])
def test_malformed_json(raw):
    assert_422(client.post("/echo", content=raw, headers=JSON_HDR))


def test_invalid_utf8_body():
    assert_422(client.post("/echo", content=b"\xff\xfe{", headers=JSON_HDR))


@pytest.mark.parametrize("raw", ["[1,2,3]", '"hi"', "42", "true", "null", "3.5", "[]"])
def test_non_object_json(raw):
    assert_422(client.post("/echo", content=raw, headers=JSON_HDR))


def test_non_object_via_json_kwarg():
    for value in ([1, 2, 3], "hi", 42, True, None):
        assert_422(client.post("/echo", json=value))


def test_empty_body_with_json_header():
    assert_422(client.post("/echo", content=b"", headers=JSON_HDR))


def test_no_body_at_all():
    assert_422(client.post("/echo"))


def test_whitespace_body():
    assert_422(client.post("/echo", content="   ", headers=JSON_HDR))


def test_valid_still_works():
    r = client.post("/echo", json={"a": [1, None]})
    assert r.status_code == 200
    assert r.json() == {"a": [1, None]}

